package com.nextaicommerce.platform.shipping;
import java.util.*;import java.nio.charset.StandardCharsets;import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Value;import tools.jackson.databind.ObjectMapper;
/** Native Amazon IDs and existing durable carrier archive. No fulfillment or stock writer. */
@Service
public class AmazonFedExSandboxShipping {
 private final boolean enabled;private final CarrierOrderContext orders;private final OrderRecipientService recipients;private final FedExSandboxRates carrier;private final CarrierConnectionRepository connections;private final FedExShipmentRepository shipments;private final ShippingLabelCrypto crypto;private final CarrierLabelComposer composer;private final ObjectMapper json;
 public AmazonFedExSandboxShipping(@Value("${app.fedex.amazon-sandbox-enabled:false}") boolean enabled,CarrierOrderContext orders,OrderRecipientService recipients,FedExSandboxRates carrier,CarrierConnectionRepository connections,FedExShipmentRepository shipments,ShippingLabelCrypto crypto,CarrierLabelComposer composer,ObjectMapper json){this.enabled=enabled;this.orders=orders;this.recipients=recipients;this.carrier=carrier;this.connections=connections;this.shipments=shipments;this.crypto=crypto;this.composer=composer;this.json=json;}
 public boolean enabled(){return enabled;}
 private void scope(UUID tenant,UUID store,String order){if(!enabled||carrier.account()==null)throw new IllegalStateException("Local Amazon FedEx shipping is disabled.");if(order==null||!order.matches("[0-9]{3}-[0-9]{7}-[0-9]{7}")||orders.shopify(tenant,store))throw new IllegalArgumentException("Choose an Amazon order in this store.");}
 private BuyShippingService.Context eligible(UUID tenant,UUID store,String order){scope(tenant,store,order);var c=orders.rateOnlyContext(tenant,store,order);if(!Set.of("Unshipped","PartiallyShipped").contains(c.order().status())||!Set.of("MFN","FBM","MERCHANT").contains(Objects.toString(c.order().fulfillmentChannel(),"").toUpperCase())||c.items().isEmpty()||c.items().stream().noneMatch(i->i.remaining()>0)||!c.committedQuantities().isEmpty())throw new IllegalStateException("Choose an eligible unshipped FBM order without another committed shipment.");return c;}
 public List<FedExShipmentRepository.Shipment> history(UUID tenant,UUID store,String order){scope(tenant,store,order);orders.context(tenant,store,order);return shipments.list(tenant,store,order).stream().filter(s->"SANDBOX".equals(s.environment())&&!s.simulated()).toList();}
 public OrderRecipientService.View recipient(UUID tenant,UUID store,String order){eligible(tenant,store,order);return recipients.localShipping(tenant,store,order);}
 static String recipientNotice(OrderRecipientService.View view){return switch(view.status()){case "LOCAL_CONNECTION_REQUIRED"->"Connect this Amazon store locally before loading its shipping address.";case "ACCESS_DENIED"->"Amazon did not authorize recipient access for this store. Review its existing app permissions.";default->"Amazon shipping address is unavailable or incomplete. Review this store connection before buying shipping.";};}
 public FedExSandboxRates.Quote quote(UUID tenant,UUID store,String order,FedExShippingService.RateOnlyInput input,String actor){
  if(!crypto.configured())throw new IllegalStateException("Configure credential encryption before using FedEx.");
  var c=eligible(tenant,store,order);if(shipments.protectedShipment(tenant,store,order)!=null)throw new IllegalStateException("A label exists or needs review. Use its saved history.");
  var view=recipients.localShipping(tenant,store,order);if(!"AVAILABLE".equals(view.status())||view.recipient()==null||!view.recipient().complete())throw new IllegalStateException(recipientNotice(view));
  var sender=c.addresses().stream().filter(a->a.id().equals(input.senderId())).findFirst().orElseThrow(()->new IllegalArgumentException("Choose a sender in this account."));var from=new FedExPayloads.Address(sender.contactName(),sender.phone(),sender.line1(),sender.city(),sender.state(),sender.postalCode(),sender.countryCode(),false);
  var parcel=FedExPackaging.normalize(input.parcel());String packageName="YOUR_PACKAGING".equals(parcel.packagingId())?"Custom packaging":FedExPackaging.option(parcel.packagingId()).label();var packing=orders.accountPacking(tenant,store,order).stream().map(l->l.withPackage(packageName)).toList();composer.validateCompact(packing);
  var rates=carrier.quote(tenant,store,from,input.recipient(),parcel);if(rates.rates().isEmpty())return rates;var connection=connections.localSandboxUat(tenant,carrier.account());var payload=FedExPayloads.rateRequest(json,carrier.account(),from,input.recipient(),parcel);UUID id=shipments.quote(tenant,store,order,connection,crypto.encrypt(payload.toString().getBytes(StandardCharsets.UTF_8)),rates.rates(),packing,actor);shipments.orderPackage(tenant,store,order,FedExShippingService.key(c),parcel);shipments.dimensions(tenant,store,FedExShippingService.key(c),parcel);return new FedExSandboxRates.Quote(rates.rates(),false,"SANDBOX","",id);
 }
 public FedExShipmentRepository.Shipment purchase(UUID tenant,UUID store,String order,UUID quote,String service){
  scope(tenant,store,order);var previous=shipments.protectedShipment(tenant,store,order);if(previous!=null){if(previous.simulated())throw new IllegalStateException("A simulated shipment needs review before genuine sandbox shipping.");if(!"PURCHASED".equals(previous.state()))throw new IllegalStateException("A prior label outcome needs review. Do not buy again.");return previous;}
  eligible(tenant,store,order);var row=shipments.list(tenant,store,order).stream().filter(s->s.id().equals(quote)&&"SANDBOX".equals(s.environment())&&!s.simulated()).findFirst().orElseThrow(()->new IllegalArgumentException("Quote is not in this Amazon store and order."));
  var frozen=json.readValue(row.packing().toString(),new tools.jackson.core.type.TypeReference<List<CarrierLabelComposer.Line>>(){});if(frozen.isEmpty()||frozen.stream().anyMatch(l->!"ACCOUNT_ITEM_V2".equals(l.format())||l.packageName()==null||l.packageName().isBlank())||!LocalFedExShippingUat.samePacking(orders.accountPacking(tenant,store,order),frozen))throw new IllegalStateException("Packing details changed. Request fresh rates before buying shipping.");
  var connection=connections.find(tenant,row.carrierId());if(!"SANDBOX".equals(connection.environment())||connection.simulated()||!carrier.account().equals(connection.accountNumber()))throw new IllegalStateException("Sandbox carrier changed.");var request=shipments.claim(tenant,store,order,quote,service,connection.revision());if(request==null)throw new IllegalStateException("Quote expired or purchase already started. Review shipment history.");
  try{var rated=(tools.jackson.databind.node.ObjectNode)json.readTree(crypto.decrypt(request.payload(),request.nonce()));var label=carrier.ship(tenant,store,FedExPayloads.shipRequest(rated,service));shipments.purchased(tenant,quote,label.trackingNumber(),crypto.encrypt(label.pdf()),null);}catch(FedExClient.CarrierException ex){shipments.failure(tenant,quote,ex.uncertain());throw ex;}catch(RuntimeException ex){shipments.failure(tenant,quote,true);throw new IllegalStateException("Label outcome needs review. Do not buy another label.");}
  return shipments.list(tenant,store,order).stream().filter(s->s.id().equals(quote)).findFirst().orElseThrow();
 }
 public byte[] label(UUID tenant,UUID store,String order,UUID id){scope(tenant,store,order);var row=history(tenant,store,order).stream().filter(s->s.id().equals(id)&&"PURCHASED".equals(s.state())).findFirst().orElseThrow(()->new IllegalArgumentException("Saved label is not in this Amazon order."));var stored=shipments.label(tenant,store,id);if(stored==null)throw new IllegalStateException("Saved label unavailable.");var packing=json.readValue(row.packing().toString(),new tools.jackson.core.type.TypeReference<List<CarrierLabelComposer.Line>>(){});return composer.compose(crypto.decrypt(stored.payload(),stored.nonce()),order,packing,CarrierLabelComposer.Layout.SANDBOX_80_20,FedExClient.Environment.SANDBOX);}
}
